INSERT INTO `announcements` VALUES (1,'Mid-Semester Examination Schedule for FYAIML','The mid-semester theoretical and practical examinations for the 3rd Semester B.Tech (AIML) will commence from November 15, 2026. Students are advised to verify their subject registrations.','Examination','all',1,'2026-10-31 05:21:37'),(2,'Annual Campus Hackathon Registrations Open','The Coding Club announces the CHARUSAT Annual Hackathon 2026. Teams of 2 to 4 students can register through the Events portal before November 10.','Events','all',1,'2026-10-31 05:21:37'),(3,'Academic Counseling Session with Assigned Mentors','Counseling meetings for Batch A, B, C, and D students with their respective faculty counselors are scheduled every Friday from 3:30 PM to 4:30 PM.','Counseling','all',1,'2026-10-31 05:21:37');
