INSERT INTO `clubs` VALUES (1,'sports','Sports Club','Athletics & Fitness','Prof. Coach Sharma','https://rockytopsportsworld.com/wp-content/uploads/2019/07/sports-balls.jpg','Promotes athletic development, fitness, and team synergy across basketball, football, volleyball, badminton, cricket, and athletics.','Promote physical fitness, organize annual sports meets, participate in inter-university championships, and instill values of discipline and sportsmanship.','2026-10-31 05:21:37'),(2,'music','Music Club','Performing Arts','Prof. Swara Joshi','https://images.unsplash.com/photo-1511671782779-c97d3d27a1d4?auto=format&fit=crop&w=1200&q=80','A vibrant community for singers, musicians, composers, and sound enthusiasts exploring Indian classical, western vocal, and contemporary music.','Provide performance platforms, organize live campus jam sessions, participate in university cultural fests, and conduct instrumental workshops.','2026-10-31 05:21:37'),(3,'coding','Coding Club','Technology & Innovation','Prof. Niyati Patel','https://media.istockphoto.com/id/1484758991/photo/hackathon-concept-the-meeting-at-the-white-office-table.jpg?s=612x612&w=0&k=20&c=ifl2F6QptCk87wh82yIX7HLILdvmoMdJeB92zr4BR6o=','Cultivates high-impact software engineering, competitive programming, AI/ML hackathons, open-source projects, and technical interview preparation.','Sharpen problem-solving skills, host 24-hour campus hackathons, facilitate collaborative GitHub projects, and conduct peer-led web and AI bootcamps.','2026-10-31 05:21:37'),(4,'photography','Photography Club','Visual Arts & Media','Prof. Darshan Shah','https://images.unsplash.com/photo-1452587925148-ce544e77e70d?auto=format&fit=crop&w=1200&q=80','Captures campus moments through digital photography, portraiture, landscape, street photography, photojournalism, and post-processing workshops.','Document official university celebrations, organize campus photo walks, host annual visual art galleries, and teach digital photo editing techniques.','2026-10-31 05:21:37');
/*!40000 ALTER TABLE `clubs` ENABLE KEYS */;
