INSERT INTO `courses` VALUES (1,'AIUE203','Web Development Fundamentals','Artificial Intelligence and Machine Learning','B.Tech',3,4,'Covers HTML5 semantic layout, responsive CSS, JavaScript ES6+, Fetch API, PHP form validation, MySQL relational architecture, and secure web development.',NULL,'2026-10-31 05:21:37'),(2,'CEUE203','Object Oriented Programming with Java','Artificial Intelligence and Machine Learning','B.Tech',3,4,'In-depth study of object-oriented paradigms, classes, inheritance, polymorphism, abstract data types, exception handling, multithreading, and Java collections.',NULL,'2026-10-31 05:21:37'),(3,'MAUE201','Discrete Mathematics & Graph Theory','Artificial Intelligence and Machine Learning','B.Tech',3,4,'Set theory, propositional logic, relations, functions, recurrence relations, combinatorics, graph theory, trees, and Boolean algebra for computation.',NULL,'2026-10-31 05:21:37'),(4,'AIUC201','Data Structures & Algorithms','Artificial Intelligence and Machine Learning','B.Tech',3,4,'Arrays, linked lists, stacks, queues, binary search trees, heaps, hashing, graph traversals, greedy methods, dynamic programming, and asymptotic analysis.',NULL,'2026-10-31 05:21:37'),(5,'CEUE204','Database Management Systems','Artificial Intelligence and Machine Learning','B.Tech',3,4,'Relational data modeling, SQL queries, normalization (1NF-BCNF), transaction processing, ACID properties, indexing, concurrency control, and query optimization.',NULL,'2026-10-31 05:21:37'),(6,'DCN201','Data Communication & Networking','Artificial Intelligence and Machine Learning','B.Tech',3,3,'OSI reference model, TCP/IP protocol suite, data link layer framing, error correction, IP addressing, subnetting, routing protocols, and socket programming.',NULL,'2026-10-31 05:21:37');
/*!40000 ALTER TABLE `courses` ENABLE KEYS */;
UNLOCK TABLES;

