INSERT INTO `events` VALUES (1,'CHARUSAT Annual Hackathon','A 24-hour rapid prototyping hackathon focusing on AI and Web applications across university teams.','Technical','2026-08-15','2026-08-15','09:00 AM - 09:00 AM (Next Day)','CSPIT Computer Center, Lab 3',100,'hackathon.jpg','upcoming','2026-10-24 16:18:21','2026-10-31 07:23:48'),(2,'Inter-College Sports Tournament','Annual multi-sport tournament featuring athletics, football, cricket, and badminton competitions.','Sports','2026-08-22','2026-08-22','08:00 AM - 05:00 PM','University Sports Complex',100,'sports.jpg','upcoming','2026-10-24 16:18:21','2026-10-31 07:23:48'),(3,'Tech Fest 2026: Innovate & Create','Flagship engineering symposium including technical paper presentations, robotics showdowns, and coding contests.','Technical','2026-09-10','2026-09-10','10:00 AM - 06:00 PM','Main University Auditorium',100,'techfest.jpg','upcoming','2026-10-24 16:18:21','2026-10-31 07:23:48'),(4,'Full-Stack Web Development Bootcamp','Hands-on masterclass on modern frontend architectures, RESTful APIs, and responsive CSS frameworks.','Workshop','2026-09-18','2026-09-18','01:00 PM - 05:00 PM','IT Department Seminar Room',100,'web_dev.jpg','upcoming','2026-10-24 16:18:21','2026-10-31 07:23:48'),(5,'Spandan Cultural Night & Talent Gala','Celebration of student artistry featuring live acoustic music, classical and modern dance, and theatrical plays.','Cultural','2026-10-02','2026-10-02','06:00 PM - 10:00 PM','Open Air Amphitheatre',100,'cultural.jpg','upcoming','2026-10-24 16:18:21','2026-10-31 07:23:48'),(6,'AI & Deep Learning Symposium','Guest lectures by industry researchers on transformer architectures, computer vision, and responsible AI.','Academic','2026-10-15','2026-10-15','10:30 AM - 03:30 PM','Central Convention Hall',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(7,'Open Source Day & Git Sprint','Collaborative contribution sprint guiding novice developers to make their first GitHub open-source PRs.','Workshop','2026-10-24','2026-10-24','11:00 AM - 04:00 PM','Software Engineering Lab 2',100,NULL,'ongoing','2026-10-31 07:23:48','2026-10-31 07:23:48'),(8,'University Chess Championship','FIDE-rated blitz and rapid chess tournaments for undergraduate and postgraduate students.','Sports','2026-10-28','2026-10-28','09:30 AM - 04:30 PM','Student Activity Centre, Hall B',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(9,'Alumni Career Mentorship Conclave','Interactive panel discussions with prominent alumni in tech, finance, and higher education abroad.','Academic','2026-11-05','2026-11-05','02:00 PM - 05:30 PM','Civil Engineering Auditorium',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(10,'Mobile App UI/UX Design Sprint','Figma-driven workshop covering design systems, wireframing, micro-interactions, and accessibility testing.','Workshop','2026-11-12','2026-11-12','10:00 AM - 03:00 PM','Multimedia Lab, Block 4',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(11,'Campus Photography Exhibition','Annual photography club showcase highlighting campus architecture, student life, and nature photography.','Cultural','2026-11-20','2026-11-20','10:00 AM - 05:00 PM','Central Library Art Gallery',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(12,'Inter-Department Badminton Cup','Singles and doubles knockout tournament for men and women across engineering faculties.','Sports','2026-12-04','2026-12-04','08:30 AM - 02:00 PM','Indoor Sports Arena',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 07:23:48'),(13,'Orientation & Induction Day 2026','Welcoming ceremony, academic curriculum overview, and club introduction fair for first-year entrants.','Academic','2026-11-15','2026-07-15','09:30 AM - 01:00 PM','University Sports Complex',100,NULL,'upcoming','2026-10-31 07:23:48','2026-10-31 08:28:43'),(14,'Cybersecurity & Ethical Hacking Clinic','Practical network penetration testing, hackathon-style capture-the-flag (CTF) challenges, and defensive security fundamentals.','Technical','2026-07-28','2026-07-28','10:00 AM - 04:00 PM','Network Security Lab',100,NULL,'completed','2026-10-31 07:23:48','2026-10-31 07:23:48'),(15,'Monsoon Music Acoustic Night','Unplugged vocal and instrumental performances by university music club bands.','Cultural','2026-08-05','2026-08-05','06:30 PM - 09:30 PM','Open Air Amphitheatre',100,NULL,'completed','2026-10-31 07:23:48','2026-10-31 07:23:48'),(16,'Cloud Computing & DevOps Workshop','Containerization with Docker, CI/CD pipeline automation, and cloud hosting architecture essentials.','Workshop','2026-08-10','2026-08-10','09:00 AM - 02:00 PM','Cloud Computing Center',100,NULL,'completed','2026-10-31 07:23:48','2026-10-31 07:23:48');
